package am.ik.rontolisp.java;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.lang.reflect.Modifier;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.jspecify.annotations.Nullable;

/**
 * The public and protected members of the JDK's classes the library has, as a running JDK
 * reflects them ({@code jdk-members.txt}, generated by {@code JavaJdkMembersTest} from
 * the JDK's public reflection; {@code .kb/java-frontend.md}, "Reflection over the JDK's
 * classes"): what {@code java.lang.reflect} answers of a class of the JDK, whose source
 * in the library is not the JDK's. The classes above them are listed too, whose members
 * {@code getMethods()} gathers, and by name the types a member names that the library
 * lacks. The lowering reads it where a program reflects over a class of the JDK; the
 * table itself is never in a compiled program.
 */
final class JavaJdkMembers {

	private static final String RESOURCE = "jdk-members.txt";

	/** A method's modifier bits a JDK sets on a bridge and on a variable arity. */
	static final int BRIDGE = 0x40;

	static final int SYNTHETIC = 0x1000;

	/** A class of the JDK as its reflection answers it. */
	static final class Type {

		/** Its binary name. */
		final String name;

		final int modifiers;

		/** The name of the module it is in. */
		final String module;

		/** The binary names of the class above it and the interfaces it declares. */
		final @Nullable String superclass;

		final List<String> interfaces;

		/** Whether its members are listed: else it is only the type of a member. */
		final boolean listed;

		final List<Member> methods = new ArrayList<>();

		final List<Member> fields = new ArrayList<>();

		final List<Member> constructors = new ArrayList<>();

		/**
		 * What {@code getMethods()} and {@code getFields()} answer, made with the table.
		 */
		List<Member> publicMethods = List.of();

		List<Member> publicFields = List.of();

		/**
		 * Its generic signature where it declares type parameters or gives a type above
		 * it type arguments ({@link Signature#ofClass}), else {@code null}.
		 */
		@Nullable String signature;

		/** Its annotations, as a JDK writes them. */
		final List<String> annotations = new ArrayList<>();

		/**
		 * The generic signature of each member whose generic types are not what they
		 * erase to.
		 */
		final Map<Member, String> signatures = new HashMap<>();

		/** The annotations of each member that carries some, as a JDK writes them. */
		final Map<Member, List<String>> memberAnnotations = new HashMap<>();

		/** The annotations of each parameter of a member, by the parameter's place. */
		final Map<Member, Map<Integer, List<String>>> parameterAnnotations = new HashMap<>();

		Type(String name, int modifiers, String module, @Nullable String superclass, List<String> interfaces,
				boolean listed) {
			this.name = name;
			this.modifiers = modifiers;
			this.module = module;
			this.superclass = superclass;
			this.interfaces = interfaces;
			this.listed = listed;
		}

		boolean isInterface() {
			return (this.modifiers & Modifier.INTERFACE) != 0;
		}

		@Override
		public String toString() {
			return this.name;
		}

	}

	/**
	 * A member: a method ({@code 'm'}), a field ({@code 'f'}) or a constructor
	 * ({@code 'k'}), at its place among its class's members of its kind.
	 *
	 * @param type what a method answers or a field holds, by binary name; a constructor's
	 * is {@code void}
	 * @param parameters the binary names of the parameters' types
	 * @param exceptions those of the types its {@code throws} clause names
	 */
	record Member(Type owner, char kind, int index, int modifiers, String name, String type, List<String> parameters,
			List<String> exceptions) {

		boolean isStatic() {
			return Modifier.isStatic(this.modifiers);
		}

		boolean isPublic() {
			return Modifier.isPublic(this.modifiers);
		}

		/** Whether a method is a bridge a compiler made, which the JDK lists. */
		boolean isBridge() {
			return this.kind == 'm' && (this.modifiers & BRIDGE) != 0;
		}

		/** Whether a method is an interface's default: neither abstract nor static. */
		boolean isDefault() {
			return this.kind == 'm' && this.owner.isInterface()
					&& (this.modifiers & (Modifier.ABSTRACT | Modifier.STATIC | Modifier.PUBLIC)) == Modifier.PUBLIC;
		}

		@Override
		public String toString() {
			return this.owner.name + "." + this.name + "(" + String.join(",", this.parameters) + ")";
		}

	}

	private static final class Holder {

		static final JavaJdkMembers SHIPPED = read();

	}

	private final Map<String, Type> types;

	private JavaJdkMembers(Map<String, Type> types) {
		this.types = types;
	}

	/** The table the jar ships. */
	static JavaJdkMembers shipped() {
		return Holder.SHIPPED;
	}

	private static JavaJdkMembers read() {
		try (InputStream in = JavaJdkMembers.class.getResourceAsStream(RESOURCE)) {
			if (in == null) {
				throw new IllegalStateException(RESOURCE + " is not in the jar");
			}
			return parse(new String(in.readAllBytes(), StandardCharsets.UTF_8));
		}
		catch (IOException ex) {
			throw new UncheckedIOException(ex);
		}
	}

	/**
	 * Reads the file: comment lines, then for each class a line {@code C name modifiers
	 * module superclass interfaces} and its members -- {@code m modifiers name returned
	 * parameters exceptions}, {@code f modifiers name type},
	 * {@code k modifiers parameters
	 * exceptions} --, a list of names joined by commas and {@code -} for none; then
	 * {@code N name modifiers module} for each type only a member names.
	 */
	static JavaJdkMembers parse(String text) {
		Map<String, Type> types = new LinkedHashMap<>();
		Type current = new Type("", 0, "", null, List.of(), false);
		Member last = null;
		for (String line : text.split("\n")) {
			if (line.isEmpty() || line.startsWith("#")) {
				continue;
			}
			String[] words = line.split(" ");
			switch (words[0]) {
				case "C" -> {
					current = new Type(words[1], Integer.parseInt(words[2]), words[3],
							words[4].equals("-") ? null : words[4], names(words[5]), true);
					types.put(current.name, current);
					last = null;
				}
				case "N" -> {
					types.put(words[1],
							new Type(words[1], Integer.parseInt(words[2]), words[3], null, List.of(), false));
					last = null;
				}
				case "m" -> {
					last = new Member(current, 'm', current.methods.size(), Integer.parseInt(words[1]), words[2],
							words[3], names(words[4]), names(words[5]));
					current.methods.add(last);
				}
				case "f" -> {
					last = new Member(current, 'f', current.fields.size(), Integer.parseInt(words[1]), words[2],
							words[3], List.of(), List.of());
					current.fields.add(last);
				}
				case "k" -> {
					last = new Member(current, 'k', current.constructors.size(), Integer.parseInt(words[1]), "<init>",
							"void", names(words[2]), names(words[3]));
					current.constructors.add(last);
				}
				case "G" -> current.signature = words[1];
				case "g" -> current.signatures.put(java.util.Objects.requireNonNull(last), words[1]);
				case "A" -> {
					if (last == null) {
						current.annotations.add(line.substring(2));
					}
					else {
						current.memberAnnotations.computeIfAbsent(last, member -> new ArrayList<>())
							.add(line.substring(2));
					}
				}
				case "p" -> current.parameterAnnotations
					.computeIfAbsent(java.util.Objects.requireNonNull(last), member -> new HashMap<>())
					.computeIfAbsent(Integer.parseInt(words[1]), place -> new ArrayList<>())
					.add(line.substring(3 + words[1].length()));
				default -> throw new IllegalStateException("a line of " + RESOURCE + " no reader knows: " + line);
			}
		}
		JavaJdkMembers table = new JavaJdkMembers(types);
		Map<Type, List<Member>> methods = new HashMap<>();
		for (Type type : types.values()) {
			if (type.listed) {
				type.publicMethods = Collections.unmodifiableList(table.gathered(type, methods));
				type.publicFields = Collections.unmodifiableList(table.gatheredFields(type));
			}
		}
		return table;
	}

	/** A type a generic signature names (JVMS 4.7.9.1). */
	sealed interface Sig permits Named, VariableSig, ArraySig, WildcardSig, PrimitiveSig {

	}

	/**
	 * A class type: its binary name, its type arguments and, for an inner class of a
	 * parameterized type, that type.
	 */
	record Named(String name, List<Sig> arguments, @Nullable Named owner) implements Sig {
	}

	record VariableSig(String name) implements Sig {
	}

	record ArraySig(Sig component) implements Sig {
	}

	/** A wildcard: {@code *}, or {@code +} or {@code -} and its bound. */
	record WildcardSig(char kind, @Nullable Sig bound) implements Sig {
	}

	record PrimitiveSig(char letter) implements Sig {
	}

	/** A type parameter a signature declares: its name and bounds. */
	record ParameterSig(String name, List<Sig> bounds) {
	}

	/**
	 * A generic signature read: the type parameters it declares and the types it names --
	 * of a class its superclass ({@code null} for an interface's) then its interfaces; of
	 * a method or a constructor its parameters, what it returns and what it throws; of a
	 * field its type.
	 */
	record Signature(List<ParameterSig> parameters, List<@Nullable Sig> types, @Nullable Sig returned,
			List<Sig> thrown) {

		/**
		 * A class's, as the table writes it: the type parameters, the superclass
		 * ({@code -} for none) and the interfaces.
		 */
		static Signature ofClass(String text) {
			SignatureReader reader = new SignatureReader(text);
			List<ParameterSig> parameters = reader.parameters();
			List<@Nullable Sig> types = new ArrayList<>();
			if (reader.peek() == '-') {
				reader.at++;
				types.add(null);
			}
			else {
				types.add(reader.type());
			}
			while (!reader.done()) {
				types.add(reader.type());
			}
			return new Signature(parameters, types, null, List.of());
		}

		/** A method's or a constructor's. */
		static Signature ofMethod(String text) {
			SignatureReader reader = new SignatureReader(text);
			List<ParameterSig> parameters = reader.parameters();
			reader.at++;
			List<@Nullable Sig> types = new ArrayList<>();
			while (reader.peek() != ')') {
				types.add(reader.type());
			}
			reader.at++;
			Sig returned = reader.type();
			List<Sig> thrown = new ArrayList<>();
			while (!reader.done()) {
				reader.at++;
				thrown.add(reader.type());
			}
			return new Signature(parameters, types, returned, thrown);
		}

		/** A field's. */
		static Signature ofField(String text) {
			return new Signature(List.of(), List.of(new SignatureReader(text).type()), null, List.of());
		}

	}

	private static final class SignatureReader {

		private final String text;

		int at;

		SignatureReader(String text) {
			this.text = text;
		}

		boolean done() {
			return this.at >= this.text.length();
		}

		char peek() {
			return this.text.charAt(this.at);
		}

		List<ParameterSig> parameters() {
			List<ParameterSig> parameters = new ArrayList<>();
			if (done() || peek() != '<') {
				return parameters;
			}
			this.at++;
			while (peek() != '>') {
				int colon = this.text.indexOf(':', this.at);
				String name = this.text.substring(this.at, colon);
				this.at = colon;
				List<Sig> bounds = new ArrayList<>();
				while (peek() == ':') {
					this.at++;
					bounds.add(type());
				}
				parameters.add(new ParameterSig(name, bounds));
			}
			this.at++;
			return parameters;
		}

		Sig type() {
			char kind = this.text.charAt(this.at++);
			return switch (kind) {
				case 'L' -> named();
				case 'T' -> {
					int end = this.text.indexOf(';', this.at);
					String name = this.text.substring(this.at, end);
					this.at = end + 1;
					yield new VariableSig(name);
				}
				case '[' -> new ArraySig(type());
				case '*' -> new WildcardSig('*', null);
				case '+', '-' -> new WildcardSig(kind, type());
				default -> new PrimitiveSig(kind);
			};
		}

		private Named named() {
			Named named = new Named(identifier().replace('/', '.'), arguments(), null);
			while (peek() == '.') {
				this.at++;
				named = new Named(named.name() + "$" + identifier(), arguments(), named);
			}
			this.at++;
			return named;
		}

		private String identifier() {
			int start = this.at;
			while (peek() != '<' && peek() != '.' && peek() != ';') {
				this.at++;
			}
			return this.text.substring(start, this.at);
		}

		private List<Sig> arguments() {
			List<Sig> arguments = new ArrayList<>();
			if (peek() == '<') {
				this.at++;
				while (peek() != '>') {
					arguments.add(type());
				}
				this.at++;
			}
			return arguments;
		}

	}

	private static List<String> names(String written) {
		return written.equals("-") ? List.of() : List.of(written.split(","));
	}

	/** The class of a binary name, or {@code null} for one the table does not have. */
	@Nullable Type of(String name) {
		return this.types.get(name);
	}

	/**
	 * {@code Class.getMethods()}'s published algorithm over the table: the public methods
	 * a class declares, then -- for a class -- those its superclass has, and those of its
	 * interfaces that are not static; of the methods sharing a name, parameter types and
	 * return type the most specific, a class's before an interface's, one below before
	 * one above. {@code JavaJdkMembersTest} holds it to a JDK's answers.
	 */
	private List<Member> gathered(Type type, Map<Type, List<Member>> done) {
		List<Member> known = done.get(type);
		if (known != null) {
			return known;
		}
		List<Member> union = new ArrayList<>();
		for (Member method : type.methods) {
			if (method.isPublic()) {
				union.add(method);
			}
		}
		Type above = type.superclass == null || type.isInterface() ? null : this.types.get(type.superclass);
		if (above != null) {
			union.addAll(gathered(above, done));
		}
		for (String name : type.interfaces) {
			Type implemented = this.types.get(name);
			if (implemented != null) {
				for (Member method : gathered(implemented, done)) {
					if (!method.isStatic()) {
						union.add(method);
					}
				}
			}
		}
		List<Member> kept = new ArrayList<>();
		for (Member method : union) {
			boolean hidden = false;
			for (Member other : union) {
				if (other != method && other.name.equals(method.name) && other.parameters.equals(method.parameters)
						&& other.type.equals(method.type) && moreSpecific(other.owner, method.owner)) {
					hidden = true;
					break;
				}
			}
			if (!hidden && !kept.contains(method)) {
				kept.add(method);
			}
		}
		done.put(type, kept);
		return kept;
	}

	/**
	 * Whether a method of one class is more specific than one of another: a class's than
	 * an interface's, one below than one above.
	 */
	private boolean moreSpecific(Type one, Type other) {
		if (!one.isInterface() && other.isInterface()) {
			return true;
		}
		return one.isInterface() == other.isInterface() && one != other && isUnder(one, other);
	}

	/** Whether a class is the other or under it, by the JDK's classes above each. */
	boolean isUnder(Type type, Type above) {
		if (type == above) {
			return true;
		}
		Type superclass = type.superclass == null ? null : this.types.get(type.superclass);
		if (superclass != null && isUnder(superclass, above)) {
			return true;
		}
		for (String name : type.interfaces) {
			Type implemented = this.types.get(name);
			if (implemented != null && isUnder(implemented, above)) {
				return true;
			}
		}
		return false;
	}

	/**
	 * {@code Class.getFields()}: the public fields a class declares, then its interfaces'
	 * and then its superclass's, each once.
	 */
	private List<Member> gatheredFields(Type type) {
		List<Member> found = new ArrayList<>();
		for (Member field : type.fields) {
			if (field.isPublic()) {
				found.add(field);
			}
		}
		List<String> above = new ArrayList<>(type.interfaces);
		if (type.superclass != null) {
			above.add(type.superclass);
		}
		for (String name : above) {
			Type next = this.types.get(name);
			if (next != null) {
				for (Member field : gatheredFields(next)) {
					if (!found.contains(field)) {
						found.add(field);
					}
				}
			}
		}
		return found;
	}

}
